// Owns a file descriptor and closes it on destruction.
class UniqueFd {
public:
    explicit UniqueFd(int fd = -1) noexcept : fd_(fd) {}
    UniqueFd(UniqueFd&& other) noexcept : fd_(std::exchange(other.fd_, -1)) {}
    UniqueFd& operator=(UniqueFd&& other) noexcept {
        if (this != &other) reset(std::exchange(other.fd_, -1));
        return *this;
    }
    UniqueFd(const UniqueFd&) = delete;
    UniqueFd& operator=(const UniqueFd&) = delete;
    ~UniqueFd() { reset(); }

    [[nodiscard]] int get() const noexcept { return fd_; }
    void reset(int fd = -1) noexcept {
        if (fd_ >= 0) ::close(fd_);
        fd_ = fd;
    }

private:
    int fd_;
};

[[noreturn]] void throw_errno(const char* what) {
    throw std::system_error(errno, std::generic_category(), what);
}

UniqueFd listen_on(std::uint16_t port) {
    UniqueFd fd(::socket(AF_INET, SOCK_STREAM, 0));
    if (fd.get() < 0) throw_errno("socket");

    const int one = 1;
    ::setsockopt(fd.get(), SOL_SOCKET, SO_REUSEADDR, &one, sizeof one);

    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    if (::bind(fd.get(), reinterpret_cast<const sockaddr*>(&addr), sizeof addr) < 0)
        throw_errno("bind");
    if (::listen(fd.get(), SOMAXCONN) < 0) throw_errno("listen");
    return fd;
}

void configure_client(int fd) {
    const int one = 1;
#ifdef SO_NOSIGPIPE
    ::setsockopt(fd, SOL_SOCKET, SO_NOSIGPIPE, &one, sizeof one);
#endif
    ::setsockopt(fd, IPPROTO_TCP, TCP_NODELAY, &one, sizeof one);
    // Don't let an idle or stalled client pin a thread forever.
    timeval timeout{.tv_sec = 30, .tv_usec = 0};
    ::setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof timeout);
    ::setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof timeout);
}

void serve_connection(UniqueFd client, const Router& router) {
    configure_client(client.get());
    static const Limits limits{};

    auto [request, error] = read_request(client.get(), limits);
    if (request) {
        Response response;
        try {
            response = router.handle(*request);
        } catch (const std::exception&) {
            response = Response::empty(500);
        }
        write_response(client.get(), response);
    } else if (error) {
        write_response(client.get(), *error);
    }
    // Half-close so the client reads the full response before the FIN.
    ::shutdown(client.get(), SHUT_WR);
}

std::optional<std::uint16_t> parse_port(std::string_view s) {
    unsigned value = 0;
    const auto [ptr, ec] = std::from_chars(s.data(), s.data() + s.size(), value);
    if (ec != std::errc{} || ptr != s.data() + s.size() || value == 0 || value > 65535)
        return std::nullopt;
    return static_cast<std::uint16_t>(value);
}

}  // namespace

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s <port>\n", argv[0]);
        return 2;
    }
    const auto port = parse_port(argv[1]);
    if (!port) {
        std::fprintf(stderr, "invalid port: %s\n", argv[1]);
        return 2;
    }

    std::signal(SIGPIPE, SIG_IGN);

    try {
        UniqueFd listener = listen_on(*port);
        KvStore store;
        const Router router(store);

        for (;;) {
            const int fd = ::accept(listener.get(), nullptr, nullptr);
            if (fd < 0) {
                if (errno == EINTR || errno == ECONNABORTED) continue;
                if (errno == EMFILE || errno == ENFILE) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(10));
                    continue;
                }
                throw_errno("accept");
            }
            // One thread per connection: connections are short-lived and the
            // required concurrency is modest.
            try {
                std::thread(serve_connection, UniqueFd(fd), std::cref(router)).detach();
            } catch (const std::system_error& e) {
                std::fprintf(stderr, "failed to spawn handler: %s\n", e.what());
            }
        }
    } catch (const std::exception& e) {
        std::fprintf(stderr, "fatal: %s\n", e.what());
        return 1;
    }
}

#include "router.hpp"

#include <algorithm>
#include <string_view>

namespace kvhttp {

namespace {

constexpr std::string_view kKvPrefix = "/kv/";
constexpr std::size_t kMaxKeyLength = 64;

bool is_valid_key(std::string_view key) {
    if (key.empty() || key.size() > kMaxKeyLength) return false;
    return std::ranges::all_of(key, [](char c) {
        return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') ||
               c == '_' || c == '-';
    });
}

Response method_not_allowed(std::string allow) {
    Response r = Response::empty(405);
    r.headers.emplace_back("Allow", std::move(allow));
    return r;
}

}  // namespace

Response Router::handle(Request& request) const {
    const std::string_view path = request.target;

    if (path == "/health") {
        if (request.method != "GET") return method_not_allowed("GET");
        return Response::make(200, "ok");
    }
    if (path == "/kv") {
        if (request.method != "GET") return method_not_allowed("GET");
        return list_keys();
    }
    if (path.starts_with(kKvPrefix)) {
        const std::string_view key = path.substr(kKvPrefix.size());
        if (!is_valid_key(key)) return Response::empty(400);
        return handle_key(request, key);
    }
    return Response::empty(404);
}

Response Router::handle_key(Request& request, std::string_view key) const {
    if (request.method == "GET") {
        auto value = store_.get(key);
        if (!value) return Response::empty(404);
        Response r;
        r.status = 200;
        r.headers.emplace_back("Content-Type", "application/octet-stream");
        r.body = std::move(value);
        return r;
    }
    if (request.method == "PUT") {
        const bool created = store_.put(std::string(key), std::move(request.body));
        return Response::empty(created ? 201 : 200);
    }
    if (request.method == "DELETE") {
        return Response::empty(store_.erase(key) ? 204 : 404);
    }
    return method_not_allowed("GET, PUT, DELETE");
}

Response Router::list_keys() const {
    // Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is needed.
    std::string json = "[";
    bool first = true;
    for (const auto& key : store_.keys()) {
        if (!first) json += ',';
        first = false;
        json += '"';
        json += key;
        json += '"';
    }
    json += ']';
    return Response::make(200, std::move(json), "application/json");
}

}  // namespace kvhttp

#pragma once

#include "http.hpp"
#include "kv_store.hpp"

namespace kvhttp {

// Maps requests onto the key/value API described in SPEC.md.
class Router {
public:
    explicit Router(KvStore& store) : store_(store) {}

    [[nodiscard]] Response handle(Request& request) const;

private:
    [[nodiscard]] Response handle_key(Request& request, std::string_view key) const;
    [[nodiscard]] Response list_keys() const;

    KvStore& store_;
};

}  // namespace kvhttp
